// RunDeadline runs a due deadline of a Problem row, a message of the queue
// ProblemDeadline, through the behaviors' core (D103), in a transaction: at
// the later of now and the time it was armed to fall due at, as the caller
// WithBehaviorCaller names, a behavior worker's, with claim, the worker's
// claim of the message, which the unit that applies its change set completes.
// Its write of the row is stamped as an operation's (operationOptions). It
// runs nothing, and says why, when the claim is lost, the row or the use is
// gone, or a guard vetoed the fire, whose message it releases to fall due
// again in a minute; any other refusal of the core's it returns as the
// *rules.Refusal it is, nothing of it written. Without a claim it runs only
// while the deadline is armed at the time it names.
func (r *ProblemRepository) RunDeadline(ctx context.Context, deadline types.ProblemDeadline, claim *rules.Claim) (*rules.DeadlineRun, error) {
	payload, err := json.Marshal(deadline.Payload)
	if err != nil {
		return nil, fmt.Errorf("orm: the payload of Problem's deadline %s.%s: %w", string(deadline.UseId), string(deadline.Name), err)
	}
	return inTransaction(ctx, r.database(), r.tx, func(tx pgx.Tx) (*rules.DeadlineRun, error) {
		return rules.RunDeadline(ctx, rulesHost(tx), "Problem", rules.Deadline{Key: deadline.RowKey.String(), UseID: string(deadline.UseId), Name: string(deadline.Name), At: int64(deadline.At), Payload: payload}, behaviorCaller(ctx), claim, r.operationOptions(ctx))
	})
}

// RunChange runs a write of a Problem row, a message of the queue
// ProblemChange, through the behaviors' core (D103), in a transaction: the
// uses that hear the row's writes, on the row as it is now, and the uses of
// other tables that hear it through a relation of the row, as the caller
// WithBehaviorCaller names, a behavior worker's, with claim, the worker's
// claim of the message, which the unit that applies its change set completes.
// Its write of the row is stamped as an operation's (operationOptions). A row
// the write left gone takes its deadlines with it. It runs nothing, and says
// why, when the claim is lost; a refusal of the core's it returns as the
// *rules.Refusal it is, nothing of it written, for the worker to fail the
// message. Without a claim it spends no message.
func (r *ProblemRepository) RunChange(ctx context.Context, change types.ProblemChange, claim *rules.Claim) (*rules.ChangeRun, error) {
	before, err := json.Marshal(change.Before)
	if err != nil {
		return nil, fmt.Errorf("orm: the image before Problem's change of %s: %w", change.RowKey.String(), err)
	}
	after, err := json.Marshal(change.After)
	if err != nil {
		return nil, fmt.Errorf("orm: the image after Problem's change of %s: %w", change.RowKey.String(), err)
	}
	return inTransaction(ctx, r.database(), r.tx, func(tx pgx.Tx) (*rules.ChangeRun, error) {
		return rules.RunChange(ctx, rulesHost(tx), "Problem", rules.Change{Key: change.RowKey.String(), Write: string(change.Write), At: int64(change.At), Before: before, After: after}, behaviorCaller(ctx), claim, r.operationOptions(ctx))
	})
}

// RunEvent hands an event of a Problem row, a message of the queue
// ProblemEvent, to handle in a transaction (D104), the repository's or one it
// opens when it has none: with claim, the worker's claim of the message, it
// first spends the message by its id and token, then runs handle with the
// transaction, so the handler's writes and the completion commit together or
// not at all; a lost claim runs nothing and says why, and handle's error is
// returned, for the worker to fail the message, and rolls back the
// transaction RunEvent opened, the spend with it. ctx reaches handle as it
// is, so the repositories' operations it runs act as the caller
// WithBehaviorCaller names, a behavior worker's. Without a claim nothing is
// spent.
func (r *ProblemRepository) RunEvent(ctx context.Context, event types.ProblemEvent, claim *rules.Claim, handle func(ctx context.Context, tx TxInterface) error) (*rules.EventRun, error) {
	return inTransaction(ctx, r.database(), r.tx, func(tx pgx.Tx) (*rules.EventRun, error) {
		run, err := rules.SpendEvent(ctx, rulesHost(tx), "Problem", claim)
		if err != nil || !run.Ran {
			return run, err
		}
		if err := handle(ctx, r.database().txOf(tx, 0)); err != nil {
			return nil, err
		}
		return run, nil
	})
}

// coreOwn is row's own fields as the behaviors' core reads them (D103), by
