func (r *ProblemRepository) operationOptions(ctx context.Context) *rules.ExecuteOptions {
	return nil
}

// createThroughCore is CreateOne on the repository's transaction: input's row
// stamped, created by the behaviors' core, whose uses initialize the fields
// they own, with the columns the insert writes, and read back.
func (r *ProblemRepository) createThroughCore(ctx context.Context, input *ProblemCreate) (*types.Problem, error) {
	row := input.row()
	columns, err := r.createColumns(row)
	if err != nil {
		return nil, err
	}
	opts := &rules.CreateOptions{ID: r.createKey(row), ExecuteOptions: rules.ExecuteOptions{OwnColumns: columns}}
	key, err := rules.RunCreate(ctx, rulesHost(r.tx), "Problem", r.coreOwn(row), behaviorCaller(ctx), opts)
	if err != nil {
		return nil, err
	}
	id, err := types.ParseIdentityUUID(key)
	if err != nil {
		return nil, fmt.Errorf("create Problem: the core's key %q: %w", key, err)
	}
	return r.GetOne(ctx, id, nil)
}

// upsertInputs are inputs as an upsert inserts them (D103): each one's row
// with the fields its behaviors own as the core's create of it gives them,
// run to its change set and not applied, so the insert writes what CreateOne
// would have, and the update, which sets none of them, leaves them as the
// row holds them. A refusal of the core's is returned before anything is
// written.
func (r *ProblemRepository) upsertInputs(ctx context.Context, inputs []*ProblemCreate) ([]*types.Problem, error) {
	host := rulesHost(r.tx)
	rows := make([]*types.Problem, 0, len(inputs))
	for _, input := range inputs {
		row := input.row()
		owned, err := rules.PrepareCreate(ctx, host, "Problem", r.coreOwn(row), behaviorCaller(ctx), &rules.CreateOptions{ID: r.createKey(row)})
		if err != nil {
			return nil, err
		}
		if value, ok := owned["status"]["status"]; ok {
			if err := json.Unmarshal(value, &row.Status); err != nil {
				return nil, fmt.Errorf("upsert Problem: the core's status.status %s: %w", value, err)
			}
		}
		if at, err := rules.TimeOfMillis(owned["status"]["enteredAt"]); err != nil {
			return nil, fmt.Errorf("upsert Problem: the core's status.enteredAt: %w", err)
		} else if at != nil {
			value := types.TemporalDateTime(*at)
			row.StatusEnteredAt = &value
		}
		rows = append(rows, row)
	}
	return rows, nil
}

// Allowed fields for Problem (for validation and ordering)
var ProblemAllowedFields = map[string]bool{
	"id":                true,
	"title":             true,
	"status":            true,
	"status_entered_at": true,
	"_version":          true,
}

// Quoted field names for Problem (for SQL generation)
var ProblemQuotedFields = map[string]string{
	"id":                `id`,
	"title":             `title`,
	"status":            `status`,
	"status_entered_at": `status_entered_at`,
	"_version":          `_version`,
}

// problemSortColumns are the columns of Problem's sort fields, by
// field, as FindPage's ORDER BY and keyset write them: qualified by the table,
// and by page_key, the alias of the subquery that reads the key's row. They
// are the only text of a sort that reaches its SQL (D60, amended). nulls is
// a column that may be null, whose nulls a page orders last (D112).
var problemSortColumns = map[ProblemSortField]struct {
	sql, key string
	nulls    bool
}{
	ProblemSortById:              {`problem.id`, `page_key.id`, false},
	ProblemSortByTitle:           {`problem.title`, `page_key.title`, false},
	ProblemSortByStatus:          {`problem.status`, `page_key.status`, false},
	ProblemSortByStatusEnteredAt: {`problem.status_entered_at`, `page_key.status_entered_at`, true},
}

// buildProblemOrderByClause builds an ORDER BY clause for Problem.
// quotedTable is the table's name as the FROM clause spells it, quoted when
// it is a keyword (a table named order is "order").
func buildProblemOrderByClause(orderBy []ProblemOrderBy, quotedTable string) string {
	if len(orderBy) == 0 {
		return ""
	}

	var clauses []string
	for _, order := range orderBy {
		fieldStr := string(order.Field)
		direction := "ASC"
		if order.Desc {
			direction = "DESC"
		}
		// Use pre-computed quoted field name
		quotedField, ok := ProblemQuotedFields[fieldStr]
		if !ok {
			quotedField = fieldStr // Fallback to unquoted if not found
		}
		clauses = append(clauses, fmt.Sprintf("%s.%s %s", quotedTable, quotedField, direction))
	}

	if len(clauses) == 0 {
		return ""
	}

	return " ORDER BY " + strings.Join(clauses, ", ")
}

func problemUUIDValue(value any) (types.IdentityUUID, bool) {
	switch v := value.(type) {
	case types.IdentityUUID:
		return v, true
	case *types.IdentityUUID:
		if v == nil {
			var zero types.IdentityUUID
			return zero, false
		}
		return *v, true
	default:
		var zero types.IdentityUUID
		return zero, false
	}
}

func problemUUIDPtr(value types.IdentityUUID) *types.IdentityUUID {
	return &value
}

// GetOne retrieves a single Problem by ID
func (r *ProblemRepository) GetOne(ctx context.Context, id types.IdentityUUID, opts *ProblemGetOptions) (*types.Problem, error) {
	// Determine if we're using partial field selection
	var fieldStrings []string
	usePartialFields := opts != nil && !opts.Fields.IsZero()

	// Build query - if no fields specified, select all in scan order
	var query string
	if usePartialFields {
		// Build selected fields in OrderedMembers order so FK columns match scan order.
		if opts.Fields.Id {
			fieldStrings = append(fieldStrings, "id")
		}
		if opts.Fields.Title {
			fieldStrings = append(fieldStrings, "title")
		}
		if opts.Fields.Status {
			fieldStrings = append(fieldStrings, "status")
		}
		if opts.Fields.StatusEnteredAt {
			fieldStrings = append(fieldStrings, "status_entered_at")
		}
		if opts.Fields.Version {
			fieldStrings = append(fieldStrings, "_version")
		}
		// Validate fields
		if err := validateFields(fieldStrings, ProblemAllowedFields); err != nil {
			return nil, err
		}
		selectFields := buildSelectFieldsTyped(fieldStrings, "problem")
		query = fmt.Sprintf(`SELECT %s FROM problem WHERE id = $1`, selectFields)
	} else {
		// Select all fields in explicit order matching scan order (using OrderedMembers for schema order)
		query = `SELECT "id", "title", "status", "status_entered_at", "_version" FROM problem WHERE id = $1`
	}

	// Execute query
	var row pgx.Row
	if r.tx != nil {
		row = r.tx.QueryRow(ctx, query, id.ToUUID())
	} else {
		row = r.db.pool.QueryRow(ctx, query, id.ToUUID())
	}

	// Scan result - when selecting all fields, scan directly into struct
	result := &types.Problem{}
	// Create temporary variables for nullable fields that need pointer scanning

	var tempStatusEnteredAt *types.TemporalDateTime

	// Create temporary variables for relationship foreign keys (we don't store these in the struct)

	var err error
	if usePartialFields {
		// Dynamic scanning for partial field selection
		// Track whether special fields were selected so we can post-process after Scan.

		var selectedStatusEnteredAt bool

		scanDest := make([]any, len(fieldStrings))
		for i, fieldName := range fieldStrings {
			switch fieldName {
			case "id":
				scanDest[i] = &result.Id
			case "title":
				scanDest[i] = &result.Title
			case "status":
				scanDest[i] = &result.Status
			case "status_entered_at":
				scanDest[i] = &tempStatusEnteredAt
				selectedStatusEnteredAt = true
			case "_version":
				scanDest[i] = &result.Version
			default:
				return nil, fmt.Errorf("unexpected field %q for Problem.GetOne", fieldName)
			}
		}

		err = row.Scan(scanDest...)
		if err == nil {
			// Copy nullable fields when present
			var jsonFieldDecodeErr error

			if selectedStatusEnteredAt && tempStatusEnteredAt != nil {
				// Nullable enum/scalar: typegen emits *Enum or *Scalar, assign pointer directly
				result.StatusEnteredAt = tempStatusEnteredAt
			}
			if jsonFieldDecodeErr != nil {
				return nil, jsonFieldDecodeErr
			}
		}
	} else {

		// Scan all fields in schema order (matches DDL column order)
		err = row.Scan(

			&result.Id,

			&result.Title,

			&result.Status,

			&tempStatusEnteredAt,

			&result.Version,
		)

		if err == nil {
			// Copy nullable fields when present

			if tempStatusEnteredAt != nil {
				// Nullable enum/scalar: typegen emits *Enum or *Scalar, assign pointer directly
				result.StatusEnteredAt = tempStatusEnteredAt
			}
		}
	}

	if err != nil {
		if err == pgx.ErrNoRows {
			return nil, ErrNotFound
		}
		return nil, fmt.Errorf("failed to scan row: %w", err)
	}

	// Hydrate relationship foreign keys into nested objects from typed field selections.

	return result, nil
}

// GetManyByIDs retrieves multiple Problem records by their IDs in a single query
func (r *ProblemRepository) GetManyByIDs(ctx context.Context, ids []types.IdentityUUID) (map[types.IdentityUUID]*types.Problem, error) {
	if len(ids) == 0 {
		return map[types.IdentityUUID]*types.Problem{}, nil
	}

	// Dedupe IDs
	seen := make(map[types.IdentityUUID]bool)
	uniqueIDs := make([]types.IdentityUUID, 0, len(ids))
	for _, id := range ids {
		if !seen[id] {
			seen[id] = true
			uniqueIDs = append(uniqueIDs, id)
		}
	}

	// Build WHERE id IN (...) clause
	placeholders := make([]string, len(uniqueIDs))
	args := make([]interface{}, len(uniqueIDs))
	for i, id := range uniqueIDs {
		placeholders[i] = fmt.Sprintf("$%d", i+1)
		args[i] = id.ToUUID()
	}

	// Build query with explicit column order
	query := fmt.Sprintf(`SELECT "id", "title", "status", "status_entered_at", "_version" FROM problem WHERE id IN (%s)`, strings.Join(placeholders, ", "))

	// Execute query
	var rows pgx.Rows
	var err error
	if r.tx != nil {
		rows, err = r.tx.Query(ctx, query, args...)
	} else {
		rows, err = r.db.pool.Query(ctx, query, args...)
	}
	if err != nil {
		return nil, fmt.Errorf("failed to execute query: %w", err)
	}
	defer rows.Close()

	// Scan results into map
	resultMap := make(map[types.IdentityUUID]*types.Problem, len(uniqueIDs))
	for rows.Next() {
		entity := &types.Problem{}

		// Create temporary variables for nullable fields that need pointer scanning

		var tempStatusEnteredAt *types.TemporalDateTime

		// Create temporary variables for relationship foreign keys (we don't store these in the struct)

		// Scan all fields in schema order (matches DDL column order)
		err := rows.Scan(

			&entity.Id,

			&entity.Title,

			&entity.Status,

			&tempStatusEnteredAt,

			&entity.Version,
		)
		if err != nil {
			return nil, fmt.Errorf("failed to scan row: %w", err)
		}

		// Copy nullable fields when present

		if tempStatusEnteredAt != nil {
			entity.StatusEnteredAt = tempStatusEnteredAt
		}

		// Set relationship IDs from scanned FK values

		entityID, ok := problemUUIDValue(entity.Id)
		if !ok {
			continue
		}
		resultMap[entityID] = entity
	}

	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("error iterating rows: %w", err)
	}

	return resultMap, nil
}

